#!/usr/bin/env bash
set -eo pipefail
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -u -B - <<'PYREMOTE'
import base64,hashlib,json,os,re,subprocess,datetime
from pathlib import Path
root=Path('/data1/home/sunyiq/knet_camels_hpc_20261012_001/attempts/state_channel_repaircheck_20261016_001_io_resume_001')
old=root.parent/'state_channel_repaircheck_20261016_001'
bundle=json.loads('{"resume_worker.py":{"base64":"","sha256":"1cfbf40ea42f8414d1d0b208476bf99778ced869b5d0fe92758e25f4a895fc7f"},"resume_controller.py":{"base64":"","sha256":"eab08860890d746ed4b7c365d4a6954db78213547678d653941c0878fd900ce8"},"resume.sbatch":{"base64":"","sha256":"f42bcdd5ad31e5eadcf63fe8e2acc596792eabbc864bea617213e501ee1e4c3a"},"recovery_contract.json":{"base64":"","sha256":"94854104ce958a2ba976c65610c7dc64effdf6885aa9789f3b6cfb851ed1bcba"}}')
for p in (root,*root.parents):assert not p.is_symlink()
root.mkdir(exist_ok=True)
for name,row in bundle.items():
 raw=base64.b64decode(row['base64'],validate=True);assert hashlib.sha256(raw).hexdigest()==row['sha256']
 p=root/name
 if p.exists():assert p.read_bytes()==raw
 else:
  with p.open('xb') as f:f.write(raw)
 if name.endswith('.py'):compile(raw,name,'exec')
contract=json.loads((root/'recovery_contract.json').read_bytes())
for name,digest in contract['original_sources'].items():assert hashlib.sha256((old/name).read_bytes()).hexdigest()==digest
receipt=json.loads((old/'runs/02092500/attempt_001/receipt.json').read_bytes())
assert receipt['status']=='FAILED' and receipt['array_job_id']=='244038' and receipt['resource_stop'] is None
assert b'TypeError: Object of type float32 is not JSON serializable' in (old/'runs/02092500/attempt_001/stdout.log').read_bytes()
assert (old/'runs/02092500/attempt_001/first_proposal.npz').is_file()
record=root/'submission.json'
if record.exists():print('IO_RESUME_SUBMISSION_JSON='+record.read_text())
else:
 intent=root/'submission_started.json'
 with intent.open('x') as f:json.dump(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),one_submission_only=True,original_job='244038',payload_sha256='76adb76b9b402bf5ca909d28921515286983494c9043d5c8f50480d0761ab4d3'),f);f.flush();os.fsync(f.fileno())
 p=subprocess.run(['sbatch',str(root/'resume.sbatch')],capture_output=True,text=True)
 (root/'sbatch_stdout.txt').write_text(p.stdout+p.stderr)
 ids=re.findall(r'Submitted batch job ([0-9]+)',p.stdout)
 assert p.returncode==0 and len(ids)==1,'Uncertain submission; inspect exact root, never replay'
 state=subprocess.run(['squeue','-r','-h','-j',ids[0],'-o','%i|%j|%T|%r|%N'],capture_output=True,text=True)
 result=dict(job_id=ids[0],root=str(root),original_array_job_id='244038',submitted_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),sbatch_reply=p.stdout,initial_queue=state.stdout,payload_sha256='76adb76b9b402bf5ca909d28921515286983494c9043d5c8f50480d0761ab4d3',original_budget_preserved=True,optimizer_updates_authorized=0)
 with record.open('x') as f:json.dump(result,f,indent=2)
 print('IO_RESUME_SUBMISSION_JSON='+json.dumps(result))

PYREMOTE
